from solution import kth_element


def test_issue_example():
    """Example: kth_element([12,3,5,7,19], 5, 2) == 3."""
    assert kth_element([12, 3, 5, 7, 19], 5, 2) == 3  # 2-1=1 -> arr[1]=3


def test_issue_first_element():
    """Rule: find the 1-indexed kth element in the given array."""
    assert kth_element([10, 20, 30, 40], 4, 1) == 10  # 1-1=0 -> arr[0]=10


def test_issue_last_element():
    """Rule: find the 1-indexed kth element in the given array."""
    assert kth_element([10, 20, 30, 40], 4, 4) == 40  # 4-1=3 -> arr[3]=40


def test_issue_middle_element():
    """Rule: find the 1-indexed kth element in the given array."""
    assert kth_element([99, 1, 50, 2, 80], 5, 3) == 50  # 3-1=2 -> arr[2]=50


def test_issue_second_position_unsorted():
    """Rule: find the kth element by position, not by sorted order."""
    assert kth_element([99, 1, 50, 2, 80], 5, 2) == 1  # 2-1=1 -> arr[1]=1


def test_issue_reverse_sorted_first():
    """Rule: find the kth element by position, not by sorted order."""
    assert kth_element([5, 4, 3, 2, 1], 5, 1) == 5  # 1-1=0 -> arr[0]=5


def test_issue_single_element():
    """Rule: find the kth element when the array has one element."""
    assert kth_element([42], 1, 1) == 42  # 1-1=0 -> arr[0]=42


def test_issue_duplicate_values_positional():
    """Rule: find the kth element by position even with duplicates."""
    assert kth_element([8, 8, 1, 8], 4, 3) == 1  # 3-1=2 -> arr[2]=1


def test_contract_string_elements():
    """Contract: kth_element works for the given array of any element type."""
    assert kth_element(["apple", "banana", "cherry"], 3, 2) == "banana"  # 2-1=1 -> arr[1]="banana"


def test_contract_negative_float_elements():
    """Contract: kth_element works for the given array of any element type."""
    assert kth_element([-5.5, 0.0, -2.5, 3.5], 4, 3) == -2.5  # 3-1=2 -> arr[2]=-2.5


def test_contract_penultimate_position():
    """Contract: kth_element(arr, n, k) returns the kth 1-indexed element."""
    assert kth_element([7, 14, 21, 28, 35, 42], 6, 5) == 35  # 5-1=4 -> arr[4]=35
